"""Project-level validation for agent projects.

Analogous to the v1 :class:`rasa.validator.Validator`: runs authoring checks
against a project *before* it is packaged (``rasa train`` packages an agent
project as a snapshot — there is no graph-training step), so misconfigurations
fail loudly at train time rather than mid-conversation.

Design (mirrors the v1 validator):

- Each check *returns* a list of
  :class:`~rasa.mantle.validation_finding.ValidationFinding` objects rather than
  raising, so every problem is collected and reported — not just the first.
  The checks themselves live next to the code they validate
  (:mod:`rasa.mantle.skills.validation`, :mod:`rasa.mantle.memory.validation`,
  :mod:`rasa.mantle.tools.validation`); this module aggregates them.
- :func:`collect_project_findings` runs all checks and returns the aggregate;
  :func:`validate_project` logs each finding (its ``code`` as the structlog event
  key) and, if any were found, raises a single terminal
  :class:`~rasa.exceptions.ValidationError` with ``code=`` so the failure is
  loggable and testable without string matching.

Checks operate on the project's own skills (``project_catalog``); cross-flow
references (``link``/``call``) and memory readability for prose ``if:``,
``@memory``, and ``execute_tool`` ``session.*`` params resolve against the
merged catalog so a project skill may target a bundled default skill or its
public memory.
"""

from __future__ import annotations

from pathlib import Path
from typing import Mapping

import structlog

from rasa.exceptions import ValidationError
from rasa.mantle.config.agent_spec import agent_spec_from_config
from rasa.mantle.config.builtin_tool_constraints import cancel_skill_confirmation
from rasa.mantle.config.validation import validate_agent, validate_integrations
from rasa.mantle.content.responses import ResponseRegistry
from rasa.mantle.content.validation import (
    load_project_responses_for_validation,
    validate_parsed_response_files,
)
from rasa.mantle.hooks.validation import validate_hooks
from rasa.mantle.memory.schema import ProjectMemorySchema
from rasa.mantle.memory.validation import (
    validate_default_skill_collect_initial_values,
    validate_memory_declarations,
    validate_project_memory_not_llm_writable,
    validate_settable_field_descriptions,
    validate_skill_memory_not_seedable,
)
from rasa.mantle.skills.catalog import (
    SkillCatalog,
    load_default_skill_catalog_result,
    load_skill_catalog_result,
)
from rasa.mantle.skills.validation import (
    collect_bare_skill_mention_findings,
    collect_bundled_default_skill_authoring_findings,
    collect_hidden_prose_skill_reference_findings,
    collect_import_tools_findings,
    collect_incomplete_memory_reference_findings,
    collect_incomplete_prose_at_token_findings,
    collect_referenced_block_findings,
    collect_referenced_skill_findings,
    collect_session_reference_in_instruction_findings,
    validate_cancel_skill_confirmation_refs,
    validate_default_skills,
    validate_execute_step_parameters,
    validate_flow_transitions,
    validate_links_and_calls,
    validate_ordered_block_structure,
    validate_precondition_bindings,
    validate_prose_instruction_scopes,
    validate_prose_memory_references,
    validate_responses_and_actions,
    validate_skill_descriptions,
    validate_skill_identifiers,
    validate_skill_loading,
    validate_tool_and_verbatim_refs,
    validate_unsupported_request_handler_override,
)
from rasa.mantle.tools.validation import (
    validate_button_source_tools,
    validate_memory_validation_tools,
    validate_tool_memory_bypass,
    validate_tool_memory_writes,
    validate_tool_references,
)
from rasa.mantle.validation_finding import ValidationFinding
from rasa.shared.project_structure import MANTLE_AGENT_FILE
from rasa.shared.utils.yaml import read_yaml_file

structlogger = structlog.get_logger()

_PROJECT_MEMORY_FILE = "memory.yml"
_PROJECT_INVALID_CODE = "mantle.validate_project.project_validation_error"


def validate_project(project_root: Path) -> None:
    """Validate an agent project directory before packaging.

    Runs every authoring check, logs each finding, and raises once if any were
    found. Called from the ``rasa train`` v2 packaging path and from
    ``rasa data validate``.

    Args:
        project_root: Directory containing the project's ``skills/`` tree,
            ``integrations.yml``, and (optionally) a top-level ``memory.yml`` /
            ``responses.yml``.

    Raises:
        rasa.exceptions.ValidationError: When one or more authoring problems are
            found. The message lists every finding; each finding is also logged
            with its own ``code`` as the structlog event key.
    """
    findings = collect_project_findings(Path(project_root))
    errors, warnings = _partition_findings(findings)
    for finding in warnings:
        structlogger.warning(
            finding.code,
            event_info=finding.message,
            docs_url=finding.docs_url,
        )
    if not errors:
        return

    for finding in errors:
        structlogger.error(
            finding.code,
            event_info=finding.message,
            docs_url=finding.docs_url,
        )

    raise ValidationError(
        code=_PROJECT_INVALID_CODE,
        event_info=_format_summary(errors),
        finding_count=len(errors),
    )


def collect_project_findings(project_root: Path) -> list[ValidationFinding]:
    """Run all authoring checks and return the aggregated findings.

    Separated from :func:`validate_project` so tests can assert on the returned
    findings' codes directly, without capturing logs or catching the exception.

    Args:
        project_root: The project directory to validate.

    Returns:
        Every :class:`~rasa.mantle.validation_finding.ValidationFinding` found,
        across all check categories. Empty when the project is valid.
    """
    project_root = Path(project_root)
    # Each skills tree is parsed exactly once; the merged catalog is built in
    # memory (project skills override defaults on duplicate id, as at runtime).
    default_result = load_default_skill_catalog_result()
    project_result = load_skill_catalog_result(
        project_root,
        inherit_flags_from=default_result.catalog.skills,
    )
    project_catalog = project_result.catalog
    merged_catalog = SkillCatalog(
        skills={**default_result.catalog.skills, **project_catalog.skills}
    )
    project_memory = _load_project_memory(project_root)
    response_registry, response_parse_findings, per_file_responses = (
        load_project_responses_for_validation(project_root)
    )
    response_names = set(response_registry.responses)

    findings: list[ValidationFinding] = []
    findings.extend(response_parse_findings)
    findings.extend(validate_skill_loading(project_result))
    findings.extend(validate_memory_declarations(project_catalog, project_memory))
    findings.extend(
        validate_project_memory_not_llm_writable(project_catalog, project_memory)
    )
    findings.extend(validate_skill_memory_not_seedable(project_catalog))
    findings.extend(
        validate_settable_field_descriptions(
            merged_catalog, project_memory, require_on=project_catalog
        )
    )
    findings.extend(validate_default_skill_collect_initial_values(merged_catalog))
    findings.extend(validate_flow_transitions(project_catalog))
    findings.extend(validate_links_and_calls(project_catalog, merged_catalog))
    findings.extend(validate_responses_and_actions(project_catalog, response_names))
    findings.extend(validate_tool_and_verbatim_refs(project_catalog, response_registry))
    findings.extend(
        _cancel_skill_confirmation_findings(project_root, response_registry)
    )
    findings.extend(
        validate_parsed_response_files(
            per_file_responses,
            catalog=merged_catalog,
            project_memory=project_memory,
        )
    )
    findings.extend(
        validate_button_source_tools(
            merged_catalog,
            per_file_responses,
            project_root,
            project_skill_ids=frozenset(project_catalog.skills),
        )
    )
    findings.extend(validate_tool_references(project_catalog, project_root))
    findings.extend(
        validate_tool_memory_writes(project_catalog, project_root, project_memory)
    )
    findings.extend(validate_tool_memory_bypass(project_catalog, project_root))
    findings.extend(
        validate_memory_validation_tools(project_catalog, project_root, project_memory)
    )
    findings.extend(validate_hooks(project_root))
    findings.extend(validate_integrations(project_root))
    findings.extend(validate_agent(project_root))
    findings.extend(
        _precondition_binding_findings(project_root, project_catalog, merged_catalog)
    )
    findings.extend(validate_default_skills(default_result))
    findings.extend(
        collect_bundled_default_skill_authoring_findings(default_result.catalog)
    )
    findings.extend(validate_unsupported_request_handler_override(project_catalog))
    findings.extend(
        validate_skill_identifiers(
            project_catalog,
            bundled_default_ids=frozenset(default_result.catalog.skills),
        )
    )
    findings.extend(validate_skill_descriptions(project_catalog))
    findings.extend(validate_ordered_block_structure(project_catalog))
    findings.extend(collect_referenced_skill_findings(merged_catalog))
    findings.extend(collect_hidden_prose_skill_reference_findings(merged_catalog))
    findings.extend(collect_bare_skill_mention_findings(merged_catalog))
    findings.extend(collect_referenced_block_findings(merged_catalog))
    findings.extend(collect_import_tools_findings(project_catalog, project_root))
    # Readable-set checks use *merged_catalog* so project prose/params may
    # reference bundled default skills' public memory (same set as runtime).
    findings.extend(validate_prose_instruction_scopes(merged_catalog, project_memory))
    findings.extend(validate_prose_memory_references(merged_catalog, project_memory))
    findings.extend(collect_incomplete_memory_reference_findings(project_catalog))
    findings.extend(collect_incomplete_prose_at_token_findings(project_catalog))
    findings.extend(collect_session_reference_in_instruction_findings(project_catalog))
    findings.extend(validate_execute_step_parameters(merged_catalog, project_memory))
    return findings


# ---------------------------------------------------------------------------
# Loading helpers
# ---------------------------------------------------------------------------


def _cancel_skill_confirmation_findings(
    project_root: Path,
    response_registry: ResponseRegistry,
) -> list[ValidationFinding]:
    """Return cancel confirmation findings when ``agent.yml`` parses as a spec.

    Identity and shape errors are already reported by :func:`validate_agent`.
    A second parse that fails is skipped so those findings are not duplicated.
    """
    agent_path = project_root / MANTLE_AGENT_FILE
    if not agent_path.is_file():
        return []
    raw_agent = read_yaml_file(str(agent_path), expand_env_vars=False)
    if not isinstance(raw_agent, Mapping):
        return []
    try:
        agent_spec = agent_spec_from_config(raw_agent)
    except ValidationError:
        return []
    confirmation = cancel_skill_confirmation(agent_spec.orchestrator.tool_constraints)
    return validate_cancel_skill_confirmation_refs(confirmation, response_registry)


def _precondition_binding_findings(
    project_root: Path,
    project_catalog: SkillCatalog,
    merged_catalog: SkillCatalog,
) -> list[ValidationFinding]:
    """Return precondition-binding findings when ``agent.yml`` parses as a spec.

    Identity and shape errors are already reported by :func:`validate_agent`.
    A second parse that fails is skipped so those findings are not duplicated.
    """
    agent_path = project_root / MANTLE_AGENT_FILE
    if not agent_path.is_file():
        return []
    raw_agent = read_yaml_file(str(agent_path), expand_env_vars=False)
    if not isinstance(raw_agent, Mapping):
        return []
    try:
        agent_spec = agent_spec_from_config(raw_agent)
    except ValidationError:
        return []
    return validate_precondition_bindings(
        project_catalog,
        merged_catalog,
        agent_spec,
    )


def _load_project_memory(project_root: Path) -> ProjectMemorySchema:
    """Load the project ``memory.yml``, or an empty schema when absent."""
    memory_path = project_root / _PROJECT_MEMORY_FILE
    if memory_path.is_file():
        return ProjectMemorySchema.from_yaml(memory_path)
    return ProjectMemorySchema()


def _partition_findings(
    findings: list[ValidationFinding],
) -> tuple[list[ValidationFinding], list[ValidationFinding]]:
    """Split findings into blocking errors and non-blocking warnings."""
    errors = [finding for finding in findings if finding.severity == "error"]
    warnings = [finding for finding in findings if finding.severity == "warning"]
    return errors, warnings


def _format_summary(findings: list[ValidationFinding]) -> str:
    """Return a multi-line summary listing every finding for the terminal error."""
    lines = [f"Project validation found {len(findings)} problem(s):"]
    lines.extend(f"  - [{finding.code}] {finding.message}" for finding in findings)
    return "\n".join(lines)
